<script setup lang="ts">
import { useForm } from '@inertiajs/vue3'; import InputError from '@/components/InputError.vue'; import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input'; import { Label } from '@/components/ui/label';
type Unit = { id: string; code: string; name: string }; type Data = { sku: string; name: string; stock_unit_id: string; conversion_to_item_base: string; is_purchasable: boolean; is_sellable: boolean; is_stockable: boolean; is_active: boolean; barcode: string; minimum_sale_price: number | null };
const props = defineProps<{ submitUrl: string; method: 'post' | 'put'; units: Unit[]; cancelUrl: string; initial?: Partial<Data> }>(); const form = useForm<Data>({ sku: props.initial?.sku ?? '', name: props.initial?.name ?? '', stock_unit_id: props.initial?.stock_unit_id ?? '', conversion_to_item_base: props.initial?.conversion_to_item_base ?? '1', is_purchasable: props.initial?.is_purchasable ?? false, is_sellable: props.initial?.is_sellable ?? false, is_stockable: props.initial?.is_stockable ?? true, is_active: props.initial?.is_active ?? true, barcode: props.initial?.barcode ?? '', minimum_sale_price: props.initial?.minimum_sale_price ?? null }); const submit = () => form.submit(props.method, props.submitUrl, { preserveScroll: true });
</script>
<template><form class="space-y-6" @submit.prevent="submit"><div class="grid gap-5 md:grid-cols-2"><div class="grid gap-2"><Label>SKU</Label><Input v-model="form.sku" required /><InputError :message="form.errors.sku" /></div><div class="grid gap-2"><Label>Nombre</Label><Input v-model="form.name" required /><InputError :message="form.errors.name" /></div><div class="grid gap-2"><Label>Unidad de existencia</Label><select v-model="form.stock_unit_id" required class="h-9 rounded-md border bg-transparent px-3 text-sm"><option value="" disabled>Selecciona</option><option v-for="unit in units" :key="unit.id" :value="unit.id">{{ unit.name }} ({{ unit.code }})</option></select><InputError :message="form.errors.stock_unit_id" /></div><div class="grid gap-2"><Label>Equivalencia en unidad base</Label><Input v-model="form.conversion_to_item_base" type="number" min="0.00000001" step="any" required /><InputError :message="form.errors.conversion_to_item_base" /></div><div class="grid gap-2"><Label>Código de barras (opcional)</Label><Input v-model="form.barcode" /><InputError :message="form.errors.barcode" /></div><div class="grid gap-2"><Label>Precio mínimo COP (opcional)</Label><Input v-model.number="form.minimum_sale_price" type="number" min="0" step="1" /><InputError :message="form.errors.minimum_sale_price" /></div><fieldset class="grid gap-2 md:col-span-2"><legend class="mb-1 text-sm font-medium">Uso de la presentación</legend><div class="flex flex-wrap gap-4"><label class="flex items-center gap-2 text-sm"><input v-model="form.is_purchasable" type="checkbox" class="size-4 accent-amber-700" />Comprable</label><label class="flex items-center gap-2 text-sm"><input v-model="form.is_sellable" type="checkbox" class="size-4 accent-amber-700" />Vendible</label><label class="flex items-center gap-2 text-sm"><input v-model="form.is_stockable" type="checkbox" class="size-4 accent-amber-700" />Inventariable</label><label class="flex items-center gap-2 text-sm"><input v-model="form.is_active" type="checkbox" class="size-4 accent-amber-700" />Activa</label></div></fieldset></div><div class="flex justify-end gap-3 border-t pt-5"><Button type="button" variant="outline" as-child><a :href="cancelUrl">Cancelar</a></Button><Button type="submit" :disabled="form.processing">Guardar presentación</Button></div></form></template>
